insert into recipe_steps (recipe_id, step_number, instruction) values
  ((select id from recipes where slug = 'garlic-butter-sirloin-steak'), 1, 'Preheat oven to 425°F (220°C). Cut potatoes into wedges, toss with olive oil and half the salt, and roast 25-30 minutes, turning once.'),
