  ((select id from recipes where slug = 'garlic-butter-sirloin-steak'), 3, 'Sear the steak in a hot pan, 3-4 minutes per side for medium-rare.'),
  ((select id from recipes where slug = 'garlic-butter-sirloin-steak'), 4, 'Add butter, garlic, and rosemary to the pan; tilt and spoon the melted butter over the steak for 1 minute.'),
  ((select id from recipes where slug = 'garlic-butter-sirloin-steak'), 5, 'Rest the steak 5 minutes, slice against the grain, and serve with the potatoes.');
